export type OpportunityStatus = "open" | "won" | "lost"

export type Opportunity = {
  id: string
  title: string
  status: OpportunityStatus
  value: number
}

export type OpportunitiesPage = { data: Opportunity[]; count: number }

// Prefixo comum: invalidar ["opportunities"] atinge todas as páginas.
export const opportunitiesQueryKey = ["opportunities"] as const

export async function fetchOpportunities(
  { page, pageSize }: { page: number; pageSize: number },
  signal?: AbortSignal,
): Promise<OpportunitiesPage> {
  const params = new URLSearchParams({ page: String(page), page_size: String(pageSize) })
  const response = await fetch(`/api/opportunities?${params}`, { signal })

  if (!response.ok) {
    const body = await response.json().catch(() => null)
    throw new Error(body?.detail ?? "Erro ao carregar oportunidades")
  }
  return response.json()
}
```

