import { keepPreviousData, useQuery } from "@tanstack/react-query"
import { useEffect, useState } from "react"

import {
  fetchOpportunities,
  opportunitiesQueryKey,
  type OpportunityStatus,
} from "../../api/opportunities"

const statusLabels: Record<OpportunityStatus, string> = {
  open: "Aberta",
  won: "Ganha",
  lost: "Perdida",
}

const currency = new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" })

type OpportunityListProps = {
  pageSize?: number
  onCreate?: () => void
}

export function OpportunityList({ pageSize = 10, onCreate }: OpportunityListProps) {
  const [page, setPage] = useState(1)

  const { data, error, isPending, isError, isPlaceholderData, refetch } = useQuery({
    queryKey: [...opportunitiesQueryKey, { page, pageSize }],
    queryFn: ({ signal }) => fetchOpportunities({ page, pageSize }, signal),
    placeholderData: keepPreviousData,
  })

  const totalPages = Math.max(1, Math.ceil((data?.count ?? 0) / pageSize))

  // Se itens foram removidos e a página atual deixou de existir, volta para a última.
  useEffect(() => {
    if (data && page > totalPages) setPage(totalPages)
  }, [data, page, totalPages])

  if (isPending) {
    return <p role="status">Carregando oportunidades…</p>
  }

  if (isError) {
    return (
      <div role="alert">
        <p>{error.message}</p>
        <button type="button" onClick={() => refetch()}>
          Tentar novamente
        </button>
      </div>
    )
  }

  if (data.count === 0) {
    return (
      <div>
        <p>Nenhuma oportunidade encontrada.</p>
        {onCreate && (
          <button type="button" onClick={onCreate}>
            Nova oportunidade
          </button>
        )}
      </div>
    )
  }

  return (
    <div>
      <table>
        <caption>Oportunidades</caption>
        <thead>
          <tr>
            <th scope="col">Título</th>
            <th scope="col">Status</th>
            <th scope="col">Valor</th>
          </tr>
        </thead>
        <tbody>
          {data.data.map((opportunity) => (
            <tr key={opportunity.id}>
              <td>{opportunity.title}</td>
              <td>{statusLabels[opportunity.status]}</td>
              <td>{currency.format(opportunity.value)}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <nav aria-label="Paginação">
        <button type="button" onClick={() => setPage((p) => p - 1)} disabled={page <= 1}>
          Anterior
        </button>
        <span>
          Página {page} de {totalPages}
        </span>
        <button
          type="button"
          onClick={() => setPage((p) => p + 1)}
          disabled={page >= totalPages || isPlaceholderData}
        >
          Próxima
        </button>
      </nav>
    </div>
  )
}
