### `src/components/Opportunities/OpportunityList.test.tsx`
```tsx
import { QueryClient, QueryClientProvider } from "@tanstack/react-query"
import { render, screen } from "@testing-library/react"
import userEvent from "@testing-library/user-event"
import { beforeEach, describe, expect, it, vi } from "vitest"

import { fetchOpportunities, type Opportunity } from "../../api/opportunities"
import { OpportunityList } from "./OpportunityList"

vi.mock("../../api/opportunities", async (importOriginal) => ({
  ...(await importOriginal<typeof import("../../api/opportunities")>()),
  fetchOpportunities: vi.fn(),
}))

const fetchMock = vi.mocked(fetchOpportunities)

function makeOpportunities(page: number, size: number): Opportunity[] {
  return Array.from({ length: size }, (_, i) => ({
    id: `${page}-${i}`,
    title: `Oportunidade ${page}.${i + 1}`,
    status: "open",
    value: 1000 * (i + 1),
  }))
}

function renderList(props: Parameters<typeof OpportunityList>[0] = {}) {
  const queryClient = new QueryClient({ defaultOptions: { queries: { retry: false } } })
  return render(
    <QueryClientProvider client={queryClient}>
      <OpportunityList {...props} />
    </QueryClientProvider>,
  )
}

describe("OpportunityList", () => {
  beforeEach(() => {
    fetchMock.mockReset()
  })

  it("mostra o carregamento enquanto a requisição está pendente", () => {
    fetchMock.mockReturnValue(new Promise(() => {}))
    renderList()
    expect(screen.getByRole("status")).toHaveTextContent("Carregando oportunidades…")
  })

  it("lista a primeira página com status, valor formatado e total de páginas", async () => {
    fetchMock.mockResolvedValue({
      data: [{ id: "1", title: "Contrato ACME", status: "won", value: 1500 }],
      count: 25,
    })
    renderList()

    expect(await screen.findByText("Contrato ACME")).toBeInTheDocument()
    expect(screen.getByText("Ganha")).toBeInTheDocument()
    expect(screen.getByText(/R\$\s*1\.500,00/)).toBeInTheDocument()
    expect(screen.getByText("Página 1 de 3")).toBeInTheDocument()
    expect(fetchMock).toHaveBeenCalledWith({ page: 1, pageSize: 10 }, expect.anything())
  })

  it("navega para a próxima página e volta", async () => {
    const user = userEvent.setup()
    fetchMock.mockImplementation(async ({ page }) => ({
      data: makeOpportunities(page, 10),
      count: 25,
    }))
    renderList()

    await screen.findByText("Oportunidade 1.1")
    await user.click(screen.getByRole("button", { name: "Próxima" }))

    expect(await screen.findByText("Oportunidade 2.1")).toBeInTheDocument()
    expect(screen.getByText("Página 2 de 3")).toBeInTheDocument()
    expect(fetchMock).toHaveBeenLastCalledWith({ page: 2, pageSize: 10 }, expect.anything())

    await user.click(screen.getByRole("button", { name: "Anterior" }))
    expect(await screen.findByText("Oportunidade 1.1")).toBeInTheDocument()
    expect(screen.getByText("Página 1 de 3")).toBeInTheDocument()
  })

  it("desabilita Anterior na primeira página e Próxima na última", async () => {
    const user = userEvent.setup()
    fetchMock.mockImplementation(async ({ page }) => ({
      data: makeOpportunities(page, page === 2 ? 5 : 10),
      count: 15,
    }))
    renderList()

    await screen.findByText("Oportunidade 1.1")
    expect(screen.getByRole("button", { name: "Anterior" })).toBeDisabled()
    expect(screen.getByRole("button", { name: "Próxima" })).toBeEnabled()

    await user.click(screen.getByRole("button", { name: "Próxima" }))
    await screen.findByText("Página 2 de 2")
    expect(screen.getByRole("button", { name: "Próxima" })).toBeDisabled()
    expect(screen.getByRole("button", { name: "Anterior" })).toBeEnabled()
  })

  it("mostra o estado vazio com a ação de criar", async () => {
    const user = userEvent.setup()
    const onCreate = vi.fn()
    fetchMock.mockResolvedValue({ data: [], count: 0 })
    renderList({ onCreate })

    expect(await screen.findByText("Nenhuma oportunidade encontrada.")).toBeInTheDocument()
    await user.click(screen.getByRole("button", { name: "Nova oportunidade" }))
    expect(onCreate).toHaveBeenCalledOnce()
  })

  it("mostra a mensagem do backend no erro e tenta de novo", async () => {
    const user = userEvent.setup()
    fetchMock
      .mockRejectedValueOnce(new Error("Sem permissão para ver oportunidades"))
      .mockResolvedValueOnce({
        data: [{ id: "1", title: "Contrato ACME", status: "open", value: 10 }],
        count: 1,
      })
    renderList()

    expect(await screen.findByRole("alert")).toHaveTextContent(
      "Sem permissão para ver oportunidades",
    )
    await user.click(screen.getByRole("button", { name: "Tentar novamente" }))
    expect(await screen.findByText("Contrato ACME")).toBeInTheDocument()
  })
})
